package dev.aura.player;
import android.media.AudioDeviceInfo;import android.os.Build;import java.util.*;
/** Present music routes, not internal voice/safe-speaker/loopback endpoints. Never merge by name alone. */
final class OutputDevices {
 record Port(int id,int type,String name,String address) {}
 static List<Port> music(List<Port> ports,int selected){Map<String,Port> unique=new LinkedHashMap<>();for(Port port:ports){int type=port.type();if(type==AudioDeviceInfo.TYPE_UNKNOWN||type==AudioDeviceInfo.TYPE_BUILTIN_EARPIECE||type==AudioDeviceInfo.TYPE_TELEPHONY||type==AudioDeviceInfo.TYPE_BUILTIN_SPEAKER_SAFE||type==AudioDeviceInfo.TYPE_REMOTE_SUBMIX||type==AudioDeviceInfo.TYPE_BUS)continue;String group=type==AudioDeviceInfo.TYPE_BUILTIN_SPEAKER?"speaker":bluetooth(type)?"bluetooth":type==AudioDeviceInfo.TYPE_USB_DEVICE||type==AudioDeviceInfo.TYPE_USB_HEADSET||type==AudioDeviceInfo.TYPE_USB_ACCESSORY?"usb":type==AudioDeviceInfo.TYPE_WIRED_HEADSET||type==AudioDeviceInfo.TYPE_WIRED_HEADPHONES?"wired":"type:"+type;String address=port.address().trim().toLowerCase(Locale.ROOT);String key=group.equals("speaker")?group:group+":"+(address.isEmpty()?"id:"+port.id():address);Port old=unique.get(key);if(old==null||port.id()==selected||old.id()!=selected&&rank(port)>rank(old))unique.put(key,port);}return new ArrayList<>(unique.values());}
 private static boolean bluetooth(int type){return type==AudioDeviceInfo.TYPE_BLUETOOTH_A2DP||type==AudioDeviceInfo.TYPE_BLUETOOTH_SCO||type==AudioDeviceInfo.TYPE_BLE_HEADSET||type==AudioDeviceInfo.TYPE_BLE_SPEAKER||type==AudioDeviceInfo.TYPE_HEARING_AID;}
 private static int rank(Port port){return port.type()==AudioDeviceInfo.TYPE_BLUETOOTH_SCO?0:1;}
 static List<AudioDeviceInfo> music(AudioDeviceInfo[] devices,int selected){List<Port> ports=new ArrayList<>();Map<Integer,AudioDeviceInfo> actual=new HashMap<>();for(var device:devices){String address=Build.VERSION.SDK_INT>=28?device.getAddress():"";ports.add(new Port(device.getId(),device.getType(),device.getProductName().toString(),address));actual.put(device.getId(),device);}List<AudioDeviceInfo> out=new ArrayList<>();for(Port port:music(ports,selected))out.add(actual.get(port.id()));return out;}
}
